func parseFilter(s string) (filter, int, error) {
    pos := 0
    for pos < len(s) && isSpace(s[pos]) { pos++ }
    st := pos
    for pos < len(s) && isIdentChar(s[pos]) { pos++ }
    if pos == st || !isIdentStart(s[st]) {
        return filter{}, 0, fmt.Errorf("bad filter in %q", s)
    }
    f := filter{name: s[st:pos]}
    for pos < len(s) && isSpace(s[pos]) { pos++ }
    if pos >= len(s) {
        return f, pos, nil
    }
    if s[pos] != ':' {
        return filter{}, 0, fmt.Errorf("bad argument for filter %q", f.name)
    }
    pos++
    for pos < len(s) && isSpace(s[pos]) { pos++ }
    if pos >= len(s) || s[pos] != '"' {
        return filter{}, 0, fmt.Errorf("missing argument for filter %q", f.name)
    }
    pos++
    var b strings.Builder
    closed := false
    for pos < len(s) {
        c := s[pos]
        switch {
        case c == '\\':
            if pos+1 >= len(s) { break outer? error }
            nxt := s[pos+1]
            if nxt == '"' || nxt == '\\' { b.WriteByte(nxt); pos += 2; continue }
            return error bad escape
        case c == '"':
            closed = true; pos++; break
        default:
            b.WriteByte(c); pos++
        }
    }
    if !closed { return error unterminated argument string }
    f.arg = b.String(); f.hasArg = true
    for pos < len(s) && isSpace(s[pos]) { pos++ }
    if pos < len(s) {
        return error unexpected trailing content
    }
    return f, pos, nil
}
```

