```
func Render(src string, data map[string]any) (string, error) {
    var out strings.Builder
    i := 0
    for i < len(src) {
        if !strings.HasPrefix(src[i:], "{{") {
            out.WriteByte(src[i]); i++
            continue
        }
        if strings.HasPrefix(src[i:], "{{{{") {
            out.WriteString("{{")
            i += 4
            continue
        }
        rest := src[i+2:]
        idx := strings.Index(rest, "}}")
        if idx < 0 {
            return "", fmt.Errorf("unterminated tag")
        }
        body := rest[:idx]
        tag, err := parseTagBody(body)
        if err != nil { return "", err }
        s, err := evalTag(tag, data)
        if err != nil { return "", err }
        out.WriteString(s)
        i += 2 + idx + 2
    }
    return out.String(), nil
}
```

